window.IAC.englishPatterns = [
  [/^(\d+\/\d+) lidos$/, '$1 read'],
  [/^(\d+) resultados? para (.*)$/, (_, n, query) => n + (n === '1' ? ' result for ' : ' results for ') + query],
  [/^(AWS|GCP) · componente do laboratório$/, '$1 · lab component'],
  [/^Catálogo (AWS|GCP)$/, '$1 catalog'],
  [/^(\d+) no projeto$/, '$1 in project'],
  [/^(\d+) recursos$/, '$1 resources'],
  [/^(\d+) no state$/, '$1 in state'],
  [/^(\d+) com drift$/, '$1 with drift'],
  [/^(\d+) arquivos · (\d+) linhas$/, '$1 files · $2 lines'],
  [/^(\d+\/\d+) passos$/, '$1 steps'],
  [/^(\d+ \/ \d+) corretas$/, '$1 correct'],
  [/^(\d+) respondidas$/, '$1 answered'],
  [/^Roteiro guiado · (AWS|GCP)$/, 'Guided scenario · $1'],
  [/^Cenário carregado no laboratório (AWS|GCP)$/, 'Scenario loaded in the $1 lab'],
  [/^(.+) adicionado$/, (_, name) => window.IAC.t(name) + ' added'],
  [/^(.+) ✓$/, (_, label) => window.IAC.t(label) + ' ✓'],
  [/^Baixado: (.+)$/, 'Downloaded: $1'],
  [/^(.+)\/mês$/, '$1/month'],
  [/^comando não encontrado: (.+)$/, 'command not found: $1'],
  [/^erro interno: (.+)$/, 'internal error: $1'],
  [/^cat: (.*): arquivo não existe$/, 'cat: $1: file does not exist'],
  [/^Este é um terminal de Terraform\. Mas a ideia é boa: quase tudo que você faz no (aws|gcloud) CLI tem equivalente declarativo\.$/, 'This is a Terraform terminal. Most operations in the $1 CLI have a declarative equivalent.'],
  [/^(╷[\s\S]*?)Rode "terraform init" primeiro\.([\s\S]*)$/, '$1Run "terraform init" first.$2']
];
